style.css:
@-moz-document url-prefix("https://www.roblox.com") {
/* Background */
  body, html {
    background: url("https://i.imgur.com/2MBC3c4.png") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #5c004d !important;
    font-family: Georgia, serif !important;
  }

  /* Navbar */
  .navbar, .navigation-container {
    background-color: #ffb6d9 !important;
    border-bottom: 3px dashed #ff66c4 !important;
    box-shadow: 0 0 10px #ffaad4 !important;
  }

  /* Buttons */
  button, .btn-primary, .btn-secondary, .btn-control {
    background-color: #ff66c4 !important;
    color: #fff !important;
    border-radius: 20px !important;
    border: 2px solid #ff99dd !important;
    text-transform: uppercase;
    font-weight: bold;
    font-family: Georgia, serif !important;
  }

  /* Hover effects */
  button:hover, .btn-primary:hover, .btn-secondary:hover {
    background-color: #ffa0e0 !important;
    box-shadow: 0 0 8px #ffaad4 !important;
  }

  /* Links */
  a {
    color: #cc3399 !important;
    text-decoration: underline dotted #ff99cc !important;
  }

  a:hover {
    color: #ff3399 !important;
    background-color: #fff0fa !important;
  }

  /* Page titles */
  h1, h2, h3 {
    font-family: Georgia, serif !important;
    color: #cc0066 !important;
    text-shadow: 1px 1px #fff0fa;
  }

  /* Avatars, icons, thumbnails */
  img {
    border-radius: 12px !important;
    border: 2px solid #ffc0f0 !important;
  }

  /* McBling sparkle cursor */
  * {
    cursor: url('https://cur.cursors-4u.net/nature/nat-11/nat1036.cur'), auto !important;
  }
}
